mapper.select:
select c.id, s.name as source_name, c.source_type, c.source_official_level, c.content_type, coalesce(c.title_zh, c.original_title) as title, c.original_title, c.summary_zh as summary, c.recommendation_reason, c.original_url, c.canonical_url, c.fact_status, c.final_score, c.featured, c.source_published_at, c.published_at from content.content_item c join source.source_entity s on s.id = c.source_entity_id where and c.featured = true
and (c.published_at, c.id) < (#{cursorPublishedAt}, #{cursorId})
order by c.published_at desc, c.id desc limit #{limit}
